mapper.select:
SELECT NULL AS band_id,
       c.chr_name AS chromosome,
       CONCAT('region:', c.chr_name, ':', #{startBp}, '-', #{endBp}) AS band_name,
       #{startBp} AS start_bp,
       #{endBp} AS end_bp,
       (
           SELECT COUNT(DISTINCT dbm.disease_id)
           FROM disease_band_map dbm
                    JOIN cytoband b2 ON b2.cytoband_id = dbm.cytoband_id
           WHERE b2.chromosome_id = c.chromosome_id
             AND b2.start_bp <= #{endBp}
             AND b2.stop_bp >= #{startBp}
       ) AS disease_count,
       (
           SELECT COUNT(DISTINCT dgm.gene_id)
           FROM disease_band_map dbm
                    JOIN cytoband b2 ON b2.cytoband_id = dbm.cytoband_id
                    JOIN disease_gene_map dgm ON dgm.disease_id = dbm.disease_id
           WHERE b2.chromosome_id = c.chromosome_id
             AND b2.start_bp <= #{endBp}
             AND b2.stop_bp >= #{startBp}
       ) AS gene_count,
       (
           SELECT COUNT(1)
           FROM small_variant sv
           WHERE sv.chromosome_id = c.chromosome_id
             AND sv.start_bp BETWEEN #{startBp} AND #{endBp}
       ) AS small_variant_count,
       (
           SELECT COUNT(1)
           FROM structural_variant stv
           WHERE stv.chromosome_id = c.chromosome_id
             AND stv.start_bp <= #{endBp}
             AND stv.end_bp >= #{startBp}
       ) AS structural_variant_count
FROM chromosome c
WHERE c.chr_name = #{chromosome}
LIMIT 1
